def count_submatrices_with_sum(ps, target):
    if not ps or not ps[0]:
        return 0
    rows, cols = len(ps), len(ps[0])
    count = 0
    for r1 in range(rows):
        for c1 in range(cols):
            for r2 in range(r1, rows):
                for c2 in range(c1, cols):
                    total = ps[r2][c2]
                    top = ps[r1 - 1][c2] if r1 > 0 else 0
                    left = ps[r2][c1 - 1] if c1 > 0 else 0
                    diag = ps[r1 - 1][c1 - 1] if r1 > 0 and c1 > 0 else 0
                    sub_sum = total - top - left + diag
                    if sub_sum == target:
                        count += 1
    return count

# Example
ps = [[1, 3, 6], [4, 7, 12], [10, 13, 18]]
print(count_submatrices_with_sum(ps, 7))
